package com.mannvaasam.service;
import com.mannvaasam.model.*; import com.mannvaasam.repo.*; import com.mannvaasam.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {final UserRepository users;final PasswordEncoder enc;final JwtService jwt;AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;} public String register(String n,String e,String p,String phone){if(users.findByEmail(e).isPresent())throw new IllegalArgumentException("Email already registered");User u=new User();u.name=n;u.email=e;u.passwordHash=enc.encode(p);u.phone=phone;u.role=Role.BUYER;users.save(u);return jwt.create(u.id,u.email,u.role.name());} public String login(String e,String p){User u=users.findByEmail(e).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!enc.matches(p,u.passwordHash)||!u.active)throw new IllegalArgumentException("Invalid credentials");return jwt.create(u.id,u.email,u.role.name());}}